 * `plan` is the org's current plan as the caller resolved it; passing it
 * records it for the org, so the bucket follows a plan change on the very
 * next request. When the plan moved since the bucket was last touched, the
 * bucket is resized keeping what was already spent in it.
 */
export async function consumeRateLimit(
  orgId: OrgId,
  bucketKey: string,
  cost = 1,
  plan?: PlanId,
): Promise<RateLimitVerdict> {
  if (plan !== undefined) setOrgPlan(orgId, plan);

  const config = configFor(orgId, bucketKey);
  const key = `${orgId}:${bucketKey}`;
  const nowMs = Date.now();

  const state = buckets.get(key) ?? {
    tokens: config.capacity,
    capacity: config.capacity,
    updatedAt: nowMs,
  };
  const carried = Math.max(0, state.tokens + config.capacity - state.capacity);
  const elapsedMinutes = (nowMs - state.updatedAt) / 60_000;
  const tokens = Math.min(
    config.capacity,
    carried + elapsedMinutes * config.refillPerMinute,
  );

  const allowed = tokens >= cost;
  const remaining = allowed ? tokens - cost : tokens;
  buckets.set(key, {
    tokens: remaining,
    capacity: config.capacity,
    updatedAt: nowMs,
