import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { eq } from "drizzle-orm";
import { getDb, subscriptions, organizations } from "@/server/db";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as billing from "@/server/services/billing-service";
import * as projectService from "@/server/services/project-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as invitationService from "@/server/services/invitation-service";
import * as webhookService from "@/server/services/webhook-service";
import * as activityService from "@/server/services/activity-service";
import * as orgService from "@/server/services/organization-service";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import { createTenant, issueInput, useTemporaryDatabase } from "$R/tests/server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

const proj = (orgId: any, name: string) => ({ orgId, name, key: "", description: null, visibility: "org" as const, leadId: null, color: "#6366f1", targetDate: null } as any);

describe("upgrade", () => {
  it("free -> growth takes effect everywhere", async () => {
    const t = await createTenant("up", "free");
    await usageRepo.recomputeUsage(t.org.id);
    const other = await createTenant("other", "free");
    await billing.changePlan(t.actors.owner, { orgId: t.org.id, plan: "growth", interval: "monthly" }).catch(e => { throw e; });
    expect((await orgRepo.findOrgById(t.org.id))!.plan).toBe("growth");
    expect((await orgRepo.findOrgById(other.org.id))!.plan).toBe("free");
    const col = getDb().select().from(organizations).where(eq(organizations.id, t.org.id)).get();
    expect(col!.plan).toBe("growth");
    await projectService.createProject(t.actors.owner, proj(t.org.id, "Two"));
    await projectService.createProject(t.actors.owner, proj(t.org.id, "Three"));
    await invitationService.inviteMember(t.actors.owner, { orgId: t.org.id, email: "x@up.test", role: "member" });
    await activityService.exportActivity(t.actors.owner, { orgId: t.org.id, format: "csv" } as any);
    const summaries = await orgService.listOrganizationsForUser(t.userIds.owner);
    expect(summaries[0]!.plan).toBe("growth");
    const issue = await issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id));
    for (let i = 0; i < 100; i++) {
      await commentService.createComment(t.actors.owner, { orgId: t.org.id, issueId: issue.id, body: "hi " + i } as any);
    }
    // other org still free-throttled
    const oi = await issueService.createIssue(other.actors.owner, issueInput(other.org.id, other.project.id));
    let denied = 0;
    for (let i = 0; i < 70; i++) {
      try { await commentService.createComment(other.actors.owner, { orgId: other.org.id, issueId: oi.id, body: "x" } as any); } catch { denied++; }
    }
    expect(denied).toBeGreaterThan(5);
    // upgrade after drain frees up capacity immediately
    await usageRepo.recomputeUsage(other.org.id);
    await getDb().update(subscriptions).set({ plan: "growth" }).where(eq(subscriptions.orgId, other.org.id)).run();
    await commentService.createComment(other.actors.owner, { orgId: other.org.id, issueId: oi.id, body: "after" } as any);
  });

  it("disagreeing records follow subscription", async () => {
    const t = await createTenant("dis", "free");
    getDb().update(subscriptions).set({ plan: "growth" }).where(eq(subscriptions.orgId, t.org.id)).run();
    await projectService.createProject(t.actors.owner, proj(t.org.id, "Two"));
    await projectService.createProject(t.actors.owner, proj(t.org.id, "Three"));
    expect((await orgRepo.findOrgBySlug("dis"))!.plan).toBe("growth");
  });

  it("no subscription falls back to org column", async () => {
    const t = await createTenant("nosub", "growth");
    getDb().delete(subscriptions).where(eq(subscriptions.orgId, t.org.id)).run();
    expect((await orgRepo.findOrgById(t.org.id))!.plan).toBe("growth");
  });

  it("growth -> starter refuses webhooks", async () => {
    const t = await createTenant("down", "growth");
    await usageRepo.recomputeUsage(t.org.id);
    await billing.changePlan(t.actors.owner, { orgId: t.org.id, plan: "starter", interval: "monthly" });
    await expect(webhookService.createWebhook(t.actors.owner, { orgId: t.org.id, url: "https://e.x/h", eventTypes: ["issue.created"], description: null } as any)).rejects.toThrow(/not included/);
  });
});

describe("trial expiry", () => {
  it("moves only trialing subs, idempotent", async () => {
    const a = await createTenant("trial-a", "growth");
    const b = await createTenant("trial-b", "growth");
    for (const t of [a, b]) {
      await usageRepo.recomputeUsage(t.org.id);
      getDb().delete((await import("@/server/db")).members).where(eq((await import("@/server/db")).members.userId, t.userIds.viewer)).run();
      await usageRepo.recomputeUsage(t.org.id);
    }
    console.log(await usageRepo.getUsage(a.org.id));
    await billing.changePlan(b.actors.owner, { orgId: b.org.id, plan: "starter", interval: "monthly" });
    const later = new Date(Date.now() + 30 * 86400000);
    const r1 = await runTrialExpiryJob(later);
    console.log(r1);
    expect((await orgRepo.findOrgById(a.org.id))!.plan).toBe("free");
    expect((await subRepo.findSubscription(b.org.id))!.plan).toBe("starter");
    expect((await orgRepo.findOrgById(b.org.id))!.plan).toBe("starter");
    await expect(projectService.createProject(a.actors.owner, proj(a.org.id, "Two"))).resolves.toBeDefined();
    await expect(projectService.createProject(a.actors.owner, proj(a.org.id, "Three"))).rejects.toThrow(/Plan free/);
    const r2 = await runTrialExpiryJob(later);
    console.log(r2);
  });
});
EOF
